# efx-presets.h
class EFXEAXREVERBPROPERTIES(object):

	def __init__(self, flDensity, flDiffusion, flGain, flGainHF, flGainLF, flDecayTime,
		flDecayHFRatio, flDecayLFRatio, flReflectionsGain, flReflectionsDelay, flReflectionsPan,
		flLateReverbGain, flLateReverbDelay, flLateReverbPan, flEchoTime, flEchoDepth,
		flModulationTime, flModulationDepth, flAirAbsorptionGainHF, flHFReference,
		flLFReference, flRoomRolloffFactor, iDecayHFLimit):

		self.flDensity = flDensity #float
		self.flDiffusion = flDiffusion #float
		self.flGain = flGain #float
		self.flGainHF = flGainHF #float
		self.flGainLF = flGainLF #float
		self.flDecayTime = flDecayTime #float
		self.flDecayHFRatio = flDecayHFRatio #float
		self.flDecayLFRatio = flDecayLFRatio #float
		self.flReflectionsGain = flReflectionsGain #float
		self.flReflectionsDelay = flReflectionsDelay #float
		self.flReflectionsPan = flReflectionsPan #float [3]
		self.flLateReverbGain = flLateReverbGain #float
		self.flLateReverbDelay = flLateReverbDelay #float
		self.flLateReverbPan = flLateReverbPan #float [3]
		self.flEchoTime = flEchoTime #float
		self.flEchoDepth = flEchoDepth #float
		self.flModulationTime = flModulationTime #float
		self.flModulationDepth = flModulationDepth #float
		self.flAirAbsorptionGainHF = flAirAbsorptionGainHF #float
		self.flHFReference = flHFReference #float
		self.flLFReference = flLFReference #float
		self.flRoomRolloffFactor = flRoomRolloffFactor #float
		self.iDecayHFLimit = iDecayHFLimit #int

